.hud{display:none;position:absolute;inset:0;pointer-events:none}
.hudtop{position:absolute;top:18px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:14px;background:#101713d9;padding:9px 18px;border:1px solid #ffffff20;clip-path:polygon(9px 0,100% 0,calc(100% - 9px) 100%,0 100%)}
.score{position:absolute;top:20px;right:34px;font-size:10px;color:#ecf0e9;text-align:right}
.objective{position:absolute;left:50%;top:75px;transform:translateX(-50%);font-size:9px;color:#e0e8dd;letter-spacing:.2em;text-shadow:0 1px 5px #000}
.topbar{position:absolute;left:34px;right:34px;top:24px;display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.14em;color:#e3e8de}
.live{display:flex;gap:9px;align-items:center;color:#d4ddce}
